"""Editorial corrections and worked learning notes, keyed to original questions.

The remainder of the machine transcription is explicitly a draft. These entries
have been compared with the supplied scan's text, choices and exact answer key.
"""
def apply(records,contexts):
 import re
 by={r['id']:r for r in records}
 def put(s,n,stem,opts,why,context=None,columns=None):
  r=by[f't01-s{s}-q{n:02}'];r.update(stem=stem,options=dict(zip('ABCDE',opts)),explanation=why,issues=[],status='reviewed',reviewed=True)
  if context:r['contextId']=context
  else:r.pop('contextId',None)
  if columns:r['columns']=dict(zip(['A','B'],columns))
  return r
 def keep(s,n,why,context=None):
  r=by[f't01-s{s}-q{n:02}']
  assert r['stem'] and set(r['options'])==set('ABCDE'),r['id']
  r.update(explanation=why,issues=[],status='reviewed',reviewed=True)
  if context:r['contextId']=context
  else:r.pop('contextId',None)
  return r
 put(1,1,'Nonviolent demonstrations often create such tensions that a community that has constantly refused to ------- its injustices is forced to correct them: the injustices can no longer be -------.',['acknowledge .. ignored','decrease .. verified','tolerate .. accepted','address .. eliminated','explain .. discussed'],'A: The community previously refused to acknowledge the injustices; demonstrations make them impossible to ignore. Both blanks must fit the same causal story.')
 put(1,2,"Since 1813 reaction to Jane Austen’s novels has oscillated between ------- and condescension; but in general later writers have esteemed her works more highly than did most of her literary -------.",['dismissal .. admirers','adoration .. contemporaries','disapproval .. readers','indifference .. followers','approbation .. precursors'],'B: Adoration contrasts with condescension. “Later writers” are contrasted with the writers who lived at Austen’s time: her contemporaries.')
 put(1,3,'There are, as yet, no vegetation types or ecosystems whose study has been ------- to the extent that they no longer ------- ecologists.',['perfected .. hinder','exhausted .. interest','prolonged .. require','prevented .. challenge','delayed .. benefit'],'B: An exhausted field has no unanswered questions left. The sentence denies that any ecosystem has reached the point of no longer interesting ecologists.')
 put(1,4,'Under ethical guidelines recently adopted by the National Institutes of Health, human genes are to be manipulated only to correct diseases for which ------- treatments are unsatisfactory.',['similar','most','dangerous','uncommon','alternative'],'E: Gene manipulation is permitted when the other available treatments are unsatisfactory. “Alternative” supplies that comparison.')
 put(1,5,"It was her view that the country’s problems had been ------- by foreign technocrats, so that to invite them to come back would be counterproductive.",['foreseen','attacked','ascertained','exacerbated','analyzed'],'D: “Counterproductive” means bringing them back would worsen the situation. Exacerbated means made worse. শনাক্ত করা আর সমস্যা বাড়ানো এক নয়।')
 put(1,6,'Winsor McCay, the cartoonist, could draw with incredible -------: his comic strip about Little Nemo was characterized by marvelous draftsmanship and sequencing.',['sincerity','efficiency','virtuosity','rapidity','energy'],'C: Marvelous drawing and sequencing demonstrate exceptional technical skill: virtuosity. The sentence gives no evidence about speed or efficiency.')
 put(1,7,"The actual ------- of Wilson’s position was always ------- by his refusal to compromise after having initially agreed to negotiate a settlement.",['outcome .. foreshadowed','logic .. enhanced','rigidity .. betrayed','uncertainty .. alleviated','cowardice .. highlighted'],'C: His refusal to compromise reveals the rigidity of his position. Here “betrayed” means revealed, rather than acted disloyally.')
 put(1,8,'SEDATIVE : DROWSINESS ::',['epidemic : contagiousness','vaccine : virus','laxative : drug','anesthetic : numbness','therapy : psychosis'],'D: A sedative produces drowsiness; an anesthetic produces numbness. Match the direction of cause and effect.')
 put(1,13,'STYGIAN : DARK ::',['abysmal : low','cogent : contentious','fortuitous : accidental','reckless : threatening','cataclysmic : doomed'],'A: Stygian means extremely dark; abysmal can mean extremely deep or low. The relation is an intensified degree, rather than simply a loose association.')
 contexts['reviewed-solar']='''It has been known for many decades that the appearance of sunspots is roughly periodic, with an average cycle of eleven years. Moreover, the incidence of solar flares and the flux of solar cosmic rays, ultraviolet radiation, and x-radiation all vary directly with the sunspot cycle. But after more than a century of investigation, the relation of these and other phenomena, known collectively as the solar-activity cycle, to terrestrial weather and climate remains unclear. For example, the sunspot cycle and the allied magnetic-polarity cycle have been linked to periodicities discerned in records of such variables as rainfall, temperature, and winds. Invariably, however, the relation is weak, and commonly of dubious statistical significance.

Effects of solar variability over longer terms have also been sought. The absence of recorded sunspot activity in the notes kept by European observers in the late seventeenth and early eighteenth centuries has led some scholars to postulate a brief cessation of sunspot activity at that time (a period called the Maunder minimum). The Maunder minimum has been linked to a span of unusual cold in Europe extending from the sixteenth to the early nineteenth centuries. The reality of the Maunder minimum has yet to be established, however, especially since the records that Chinese naked-eye observers of solar activity made at that time appear to contradict it. Scientists have also sought evidence of long-term solar periodicities by examining indirect climatological data, such as fossil records of the thickness of ancient tree rings. These studies, however, failed to link unequivocally terrestrial climate and the solar-activity cycle, or even to confirm the cycle’s past existence.

If consistent and reliable geological or archaeological evidence tracing the solar-activity cycle in the distant past could be found, it might also resolve an important issue in solar physics: how to model solar activity. Currently, there are two models of solar activity. The first supposes that the Sun’s internal motions (caused by rotation and convection) interact with its large-scale magnetic field to produce a dynamo, a device in which mechanical energy is converted into the energy of a magnetic field. In short, the Sun’s large-scale magnetic field is taken to be self-sustaining, so that the solar-activity cycle it drives would be maintained with little overall change for perhaps billions of years. The alternative explanation supposes that the Sun’s large-scale magnetic field is a remnant of the field the Sun acquired when it formed, and is not sustained against decay. In this model, the solar mechanism dependent on the Sun’s magnetic field runs down more quickly. Thus, the characteristics of the solar-activity cycle could be expected to change over a long period of time. Modern solar observations span too short a time to reveal whether present cyclical solar activity is a long-lived feature of the Sun, or merely a transient phenomenon.'''
 put(1,17,'The author focuses primarily on',['presenting two competing scientific theories concerning solar activity and evaluating geological evidence often cited to support them','giving a brief overview of some recent scientific developments in solar physics and assessing their impact on future climatological research','discussing the difficulties involved in linking terrestrial phenomena with solar activity and indicating how resolving that issue could have an impact on our understanding of solar physics','pointing out the futility of a certain line of scientific inquiry into the terrestrial effects of solar activity and recommending its abandonment in favor of purely physics-oriented research','outlining the specific reasons why a problem in solar physics has not yet been solved and faulting the overly theoretical approach of modern physicists'],'C: Paragraphs 1–2 describe uncertain Earth–Sun links; paragraph 3 explains how reliable long-term evidence could distinguish two solar models. C covers both parts without inventing criticism or abandonment.','reviewed-solar')
 put(1,18,'Which statement about the two models of solar activity described in the final paragraph is accurate?',['In both models cyclical solar activity is regarded as a long-lived feature of the Sun, persisting with little change over billions of years.','In both models the solar-activity cycle is hypothesized as being dependent on the large-scale solar magnetic field.','In one model the Sun’s magnetic field is thought to play a role in causing solar activity, whereas in the other model it is not.','In one model solar activity is presumed unrelated to terrestrial phenomena, whereas in the other it is thought to have observable effects on Earth.','In one model cycles longer than a few decades are considered impossible, whereas in the other such cycles are predicted.'],'B: Both models depend on the large-scale magnetic field. They differ in whether that field sustains itself or decays, not in whether it has a role.','reviewed-solar')
 put(1,19,'According to the passage, why are late seventeenth- and early eighteenth-century Chinese records important?',['They suggest that the data on which the Maunder minimum was predicated were incorrect.','They suggest that the Maunder minimum cannot be related to climate.','They suggest that the Maunder minimum might be valid only for Europe.','They establish a span of unusually cold weather worldwide at the time of the Maunder minimum.','They establish that solar activity at the time did not significantly vary from its present pattern.'],'A: The Chinese records apparently contradict the European evidence for an absence of sunspots. The passage does not say they establish a worldwide climate pattern.','reviewed-solar')
 put(1,20,'What does the author imply about currently available geological and archaeological evidence concerning the solar-activity cycle?',['It best supports the self-sustaining magnetic-field model.','It best supports the decaying magnetic-field model.','It is insufficient to confirm either model of solar activity described in the third paragraph.','It contradicts both models as presented.','It disproves the theory that terrestrial weather and solar activity are linked.'],'C: The passage asks for consistent, reliable long-term evidence precisely because existing evidence does not resolve the models. “Not confirmed” does not mean “disproved.”','reviewed-solar')
 put(1,21,'Which finding would strengthen the self-sustaining magnetic-field model?',['Intense volcanic eruptions in the distant past occurred in cycles with very long periodicities.','Current global thunderstorm activity rises and falls in approximately eleven-year cycles.','Distant climatic changes had periodicities longer than two hundred years.','The sunspot cycle’s length varied by up to two years in the last century.','Hundreds of millions of years ago, solar-activity cycles displayed the same periodicities as present-day cycles.'],'E: This model predicts little overall change across very long periods. Evidence of unchanged ancient periodicities directly supports that distinctive prediction.','reviewed-solar')
 put(1,22,'What can be inferred about Chinese observations during the late seventeenth and early eighteenth centuries?',['They are ambiguous because most sunspots cannot be seen with the naked eye.','They were probably made under the same weather conditions as European observations.','They are more reliable than European observations made during this period.','They record some sunspot activity during this period.','They have been used to argue that a change in solar activity occurred during this period.'],'D: To contradict an absence of sunspot activity, the Chinese records must show some activity. The passage does not establish their superior reliability.','reviewed-solar')
 put(1,23,'Studies using tree-ring thickness to link solar periodicity and terrestrial climate depend on which assumption?',['The solar-activity cycle had its present form when the trees grew.','The biological mechanisms of tree growth are unaffected by short-term weather patterns.','Average tree-ring thickness varies from species to species.','Tree-ring thicknesses reflect changes in terrestrial climate.','Terrestrial climate and the solar-activity cycle both affect tree-ring thickness randomly.'],'D: Tree rings can serve as indirect climate evidence only if their thickness reflects climate. This is the necessary bridge between the measured record and the proposed relationship.','reviewed-solar')
 vocab=[
 (28,'FALLACY',['personal philosophy','imaginative idea','unconfirmed theory','tentative opinion','valid argument'],'E: A fallacy is faulty reasoning; a valid argument is the opposite.'),
 (29,'DIVULGE',['keep secret','evaluate by oneself','refine','restore','copy'],'A: Divulge means disclose. Its opposite is keep secret.'),
 (30,'BOYCOTT',['extort','underwrite','underbid','stipulate','patronize'],'E: To boycott is to refuse to buy from or support; to patronize is to buy from or support.'),
 (31,'ADULTERATION',['consternation','purification','normalization','approximation','rejuvenation'],'B: Adulteration introduces impurities; purification removes them.'),
 (32,'DEPOSITION',['process of congealing','process of distilling','process of eroding','process of evolving','process of condensing'],'C: In the geological sense, deposition lays material down; erosion wears it away. Use the sense suggested by the choices.'),
 (33,'ENERVATE',['recuperate','resurrect','renovate','gather','strengthen'],'E: Enervate means weaken, not energize. Strengthen is its opposite.'),
 (34,'LOQUACIOUS',['tranquil','skeptical','morose','taciturn','witty'],'D: Loquacious means talkative; taciturn means habitually uncommunicative.'),
 (35,'REPINE',['intensify','excuse','express joy','feel sure','rush forward'],'C: Repine means complain or feel discontent. Express joy reverses that attitude.'),
 (36,'VENERATION',['derision','blame','avoidance','ostracism','defiance'],'A: Veneration is deep respect; derision is contemptuous mockery.'),
 (37,'INVETERATE',['casual','public','satisfactory','trustworthy','sophisticated'],'A: Inveterate describes a deeply established habit. Casual contrasts with that entrenched quality.'),
 (38,'UNDERMINE',['submerge','supersede','overhaul','undergird','intersperse'],'D: Undermine means weaken a foundation; undergird means support or strengthen it.')]
 for n,w,o,e in vocab:put(1,n,w+': choose the word or phrase most nearly opposite in meaning.',o,e)
 contexts['reviewed-cups']='Six inverted cups stand in a straight line, numbered 1 through 6. Each hides exactly one ball. The six colors are green, magenta, orange, purple, red and yellow. Purple is under a lower-numbered cup than orange. Red and magenta are under immediately adjacent cups. Green is under cup 5.'
 put(2,1,'Which could be the colors under cups 1 through 6, in order?',['Green, yellow, magenta, red, purple, orange','Magenta, green, purple, red, orange, yellow','Magenta, red, purple, yellow, green, orange','Orange, yellow, red, magenta, green, purple','Red, purple, magenta, yellow, green, orange'],'C: This arrangement puts green at 5, red beside magenta, and purple before orange. Check the fixed position first to eliminate quickly.','reviewed-cups')
 put(2,2,'If the magenta ball is under cup 4, the red ball must be under cup',['1','2','3','5','6'],'C: Red must be beside magenta, hence at 3 or 5. Green already occupies 5, so red is at 3.','reviewed-cups')
 put(2,3,'A ball of which color could be under cup 6?',['Green','Magenta','Purple','Red','Yellow'],'E: Green is fixed at 5, so neither red nor magenta can be at 6, because its partner would need 5. Purple needs an orange after it. Yellow can be at 6.','reviewed-cups')
 put(2,4,'If the purple ball is under cup 4, the orange ball must be under cup',['1','2','3','5','6'],'E: Orange must be after purple. Cup 5 is occupied by green, leaving cup 6.','reviewed-cups')
 put(2,5,'Which must be true?',['Green is under a lower-numbered cup than yellow.','Orange is under a lower-numbered cup than green.','Purple is under a lower-numbered cup than green.','Purple is under a lower-numbered cup than red.','Red is under a lower-numbered cup than yellow.'],'C: Purple cannot occupy 5 because green does. It cannot occupy 6 because orange must come after it. Therefore purple is before cup 5.','reviewed-cups')
 put(2,6,'If orange is under cup 2, which pair could occupy immediately adjacent cups?',['Green and magenta','Green and purple','Orange and yellow','Purple and red','Red and yellow'],'A: Purple is then at 1. Red and magenta can occupy 3 and 4, with magenta at 4 beside green at 5; yellow occupies 6.','reviewed-cups')
 put(2,7,'If magenta is under cup 1, which pair must occupy immediately adjacent cups?',['Green and orange','Green and yellow','Purple and red','Purple and yellow','Red and yellow'],'A: Red is at 2. Purple cannot be at 6 and cannot take green’s 5, so orange must be at 4 or 6. In either case it is beside green at 5.','reviewed-cups')
 for n,why in [(8,'B: Standard 42 requires action when an accident is foreseeable. Whether this type of defect is known to indicate an accident directly tests that condition; seriousness after the event does not.'),(9,'B: Matching a legend to a historical king only works if the legend has some historical basis. If Arthur were wholly fictional, the resemblance would not establish a model.'),(10,'E: Recovering and reusing the coolants can prevent their release. This attacks the claim that no further ozone damage can be prevented, even though some chemicals already exist.'),(23,'B: A schooling fish signals more fish nearby; a solitary flounder does not. This explains following one returning bird but not another without changing the birds’ food preferences.'),(24,'C: Productive workers may be rewarded with nicer offices. That reverses the proposed causal direction, so the observed correlation need not show that offices caused productivity.'),(25,'E: Most switchers may enter Union while many existing Union members leave party politics altogether. Inflow can therefore be balanced by outflow.')]:
  r=keep(2,n,why);r['topic']='critical-reasoning'
 contexts['reviewed-embassies']='Six workers (Farr, Golden, Hayakawa, Inserra, Jones and Kovacs) are assigned to four embassies. L and M have dry climates; P and T have humid climates. Each embassy receives at least one worker. At least one humid embassy receives at least two. Golden and Kovacs cannot share an embassy. Inserra must be in a dry climate; Jones must be in a humid climate.'
 put(2,11,'Which is an acceptable assignment? Each option lists L; M; P; T.',['Farr, Golden; Inserra, Kovacs; Hayakawa; Jones','Golden, Kovacs; Inserra; Jones; Farr, Hayakawa','Golden; Farr, Inserra; Kovacs; Jones, Hayakawa','Jones; Golden, Inserra; Hayakawa; Farr, Kovacs','Kovacs; Farr, Hayakawa; Inserra; Golden, Jones'],'C: This assignment meets every rule. A has no humid embassy with two workers; B puts Golden with Kovacs; D puts Jones in dry L; E puts Inserra in humid P.','reviewed-embassies')
 put(2,12,'Who must be assigned to either L or M?',['Farr','Golden','Hayakawa','Inserra','Kovacs'],'D: Inserra must be in a dry climate, and the only dry embassies are L and M.','reviewed-embassies')
 put(2,13,'Which cannot be true?',['One worker is assigned to L.','Two workers are assigned to P.','Two workers are assigned to L.','Three workers are assigned to M.','Three workers are assigned to T.'],'D: Three at dry M plus one at each other embassy uses all six workers. No humid embassy then has the required second worker.','reviewed-embassies')
 put(2,14,'If Golden and Kovacs are assigned to L and M respectively, which must be true?',['Farr is assigned to either P or T.','Inserra is assigned to either P or T.','P and T each have two workers.','Hayakawa is assigned to L.','Hayakawa is assigned to T.'],'A: Inserra must also be dry, giving at least three dry workers. Farr, Hayakawa and Jones must therefore all be humid to populate both humid embassies and double one of them.','reviewed-embassies')
 put(2,15,'If Golden, Hayakawa and Kovacs are among the workers assigned to humid embassies, which must be true?',['Farr is assigned to an embassy with none of the other five workers.','Golden is assigned to an embassy with none of the other five workers.','Jones is assigned to the same embassy as Kovacs.','Hayakawa is assigned to the same embassy as Golden.','Hayakawa is assigned to the same embassy as Kovacs.'],'A: Jones is also humid, so four workers are humid. Only Farr and Inserra remain to fill both dry embassies. Each must be alone.','reviewed-embassies')
 contexts['reviewed-roads']='Road network: two-way links are 1–2, 1–3, 1–5, 2–6, 3–7, 5–6 and 6–7. One-way links are 2→4, 3→2 and 4→3. There are no other roads. The volunteer always chooses a complete-trip route passing through the fewest points; a repeated point counts again. Home: 3. Supermarket: 1. Clothing store: 5. Bakery: 4. Tutoring center: 2. Distribution center: 6. Shelter: 7.'
 put(2,16,'Starting at the supermarket and next going to the shelter, what must be the first intermediate point?',['2','3','5','6','7'],'B: The shortest path is 1→3→7, so its intermediate point is 3.','reviewed-roads')
 put(2,17,'Starting from home, the volunteer makes pickups at the supermarket and bakery in either order. What must be the first two intermediate points?',['1 and 2','1 and 3','2 and 1','2 and 4','4 and 2'],'A: The shortest complete route visits the supermarket first: 3→1→2→4. Visiting the bakery first requires returning through additional points to reach 1.','reviewed-roads')
 put(2,18,'Starting at the clothing store, the volunteer picks up bread at either the supermarket or bakery, choosing the shorter complete route, and then goes to the shelter. What must be the first two points after the clothing store?',['1 and 2','1 and 3','4 and 2','6 and 2','6 and 4'],'B: Via the supermarket, the route is 5→1→3→7. A bakery detour is longer, so the first two points are 1 and 3.','reviewed-roads')
 put(2,19,'The trip starts at the shelter, next goes to the bakery, and ends at the distribution center. What can be the first two intermediate points?',['3 and 1','3 and 4','4 and 2','6 and 2','6 and 5'],'D: A shortest route starts 7→6→2→4 and then continues from the bakery 4→3→2→6 or 4→3→7→6. The directed roads rule out reversing 4→3.','reviewed-roads')
 contexts['reviewed-houses']='Seven styles of house are Q, R, S, T, W, X and Z. Every block has at least three styles. Any block with Z also has W. Any block adjacent to a block with both S and X must have T and Z. No block adjacent to one with both R and Z can have T or W. No block can have both S and Q.'
 put(2,20,'Which can be the complete selection of styles on a block?',['Q, R, S','Q, S, X','R, T, Z','S, W, Z','T, X, Z'],'D: S, W, Z obeys the within-block rules. A and B combine S with Q; C and E contain Z without W.','reviewed-houses')
 put(2,21,'Which style must be on a block adjacent to one containing only S, T, W, X and Z?',['Q','R','S','W','X'],'D: The neighboring block has S and X, so this block needs T and Z. Having Z also requires W.','reviewed-houses')
 put(2,22,'Which can be the complete selection for a block adjacent to exactly one block, whose styles are S, T, W and X only?',['S, T, X','T, X, Z','R, S, X, Z','S, T, W, X','T, W, X, Z'],'E: The given neighbor has S and X, requiring T and Z; Z requires W. E includes all three without forcing a contradictory condition back onto its neighbor.','reviewed-houses')
 compare=['Column A is greater','Column B is greater','The quantities are equal','The relationship cannot be determined']
 def qc(n,stem,a,b,why,topic):
  r=put(3,n,stem,compare,why,columns=[a,b]);r['topic']=topic
 qc(1,'Compare the quantities.','3⁴','4³','A: 3⁴ = 81, while 4³ = 64. A larger base does not always give the larger power.','number')
 qc(5,'Square MNPQ has area 36. An equilateral triangle NOP is built outward on its side NP. Compare.','The perimeter of pentagon MNOPQ','30','C: The square side is 6. The outer pentagon has five sides of length 6, giving perimeter 30. The three equal triangle angles in the original figure are expressed in words.','geometry')
 qc(7,'|−3| = −m. Compare.','m','3','B: |−3| = 3 = −m, so m = −3. Therefore 3 is greater.','number')
 qc(2,'x = 2y + 3 and y = −2. Compare the quantities.','x','−1','C: Substitute y = −2: x = 2(−2) + 3 = −1. The quantities are equal.','algebra')
 qc(3,'d = 5.03894. Let [d] be d rounded to the nearest thousandth. Compare the quantities.','The number of decimal places where d and [d] differ','4','B: [d] = 5.03900. The thousandths, ten-thousandths and hundred-thousandths digits differ: three places. 3 < 4.','number')
 qc(4,'x + 2y > 8. Compare the quantities.','2x + 4y','20','D: Doubling gives 2x + 4y > 16. That may be below, equal to or above 20. An inequality bound is not an exact value.','algebra')
 qc(6,'p and q are different primes. r is the least prime greater than p; s is the least prime greater than q. Compare.','r − p','s − q','D: Prime gaps vary. p = 2, q = 3 gives gaps 1 and 2; reversing p and q reverses the comparison.','number')
 qc(8,'n is an even integer and a multiple of 3. Compare.','The remainder when n is divided by 12','6','D: n can be 6 (remainder 6) or 12 (remainder 0). The comparison can be equal or Column B greater.','number')
 qc(9,'Equilateral triangle PQR joins the centers of three pairwise externally tangent congruent circles. Compare.','The perimeter of triangle PQR','The circumference of the circle with center Q','B: If each circle has radius r, each triangle side is 2r. Its perimeter is 6r, while the circumference is 2πr > 6r. The original geometric information is expressed here in words.','geometry')
 qc(10,'Compare the volumes.','A cylindrical tank with radius 2 m and height 10 m','A cylindrical tank with radius 1 m and height 20 m','A: V = πr²h. The volumes are 40π and 20π cubic meters; radius is squared.','geometry')
 qc(11,'d and s are nonzero distance and speed quantities. Compare travel times.','Time to travel d miles at s miles per hour','Time to travel d/2 miles at 2s miles per hour','A: The times are d/s and (d/2)/(2s) = d/(4s). Column A is four times Column B.','word-problems')
 qc(15,'Maria’s old salary was 24% more than Julio’s. Her new salary is 24% less than her old salary. Compare.','Julio’s salary','Maria’s new salary','A: Let Julio earn 100. Maria’s old salary is 124 and her new salary is 124 × 0.76 = 94.24. Equal percentage changes on different bases do not cancel.','percent')
 put(3,16,'(19 − 18 − 17 − 16) − (20 − 19 − 18 − 17) =',['−36','−6','−4','1','2'],'E: The bracket values are −32 and −34. Therefore −32 − (−34) = 2.')['topic']='number'
 put(3,17,'If 3x − 2 = 7, then 4x =',['3','5','7','9','12'],'E: 3x = 9, so x = 3 and 4x = 12.')['topic']='algebra'
 put(3,20,'What is the greatest number of diagonals that can be drawn from one vertex of a regular six-sided polygon?',['2','3','4','5','6'],'B: A vertex cannot connect by a diagonal to itself or its two neighbors. The number is n − 3 = 6 − 3 = 3.')['topic']='geometry'
 put(3,26,'If 0 < st < 1, which can be true?',['s < −1 and t > 0','s < −1 and t < −1','s > −1 and t < −1','s > 1 and t < −1','s > 1 and t > 1'],'C: For example, s = −0.5 and t = −1.5 give st = 0.75. A and D give negative products; B and E give products greater than 1.')['topic']='algebra'
 put(3,27,'Points W, X, Y and Z lie in that order on a line segment. WY = 21, XZ = 26, and YZ is twice WX. Find XY.',['5','10','11','16','Cannot be determined'],'D: Let WX = a and XY = b. Then a + b = 21 and b + 2a = 26. Subtract to get a = 5, hence b = 16. The original line diagram is restated in words.')['topic']='geometry'
 # Every editorial solution must agree with the original answer key.
 for r in records:
  if r.get('reviewed'):
   # Hand-reviewed line-wrap repairs in the six argument items retained above.
   for key in ['stem','options']:
    values=r[key] if key=='options' else {'stem':r[key]}
    for k,v in values.items():
     v=v.replace('y~rs','years').replace("party at all. '",'party at all.')
     for word in ['mysteriously','additional','activities','historical','embellish','refrigeration','potentially','refrigerators','property','fighting','productivity','surroundings','productive','physical','employees','responsible','foreseeable','abandoned','political','affiliation','per capita']:
      for pos in range(2,len(word)-1):v=re.sub(r'\b'+re.escape(word[:pos])+r'\s*\n\s*'+re.escape(word[pos:])+r'\b',word,v,flags=re.I)
     values[k]=v
    if key=='stem':r[key]=values['stem']
   assert r['explanation'].startswith(r['answer']+':'),(r['id'],r['answer'],r['explanation'])
